<div class="topline"><span>OPTIONAL WORKSPACE</span><span>Local records for a small business.</span></div><header class="page-header"><div><h1>Small business</h1><p class="muted">Track clients, project hours, income and costs. These are separate from personal Money accounts.</p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<section class="card"><h2>New project</h2><form class="form-grid" method="post" action="/small-business/project"><?= csrf_field() ?><label>Project name<input name="name" maxlength="200" required></label><label>Client<input name="client" maxlength="200"></label><label>Hourly rate (Rs., optional)<input type="number" name="hourly_rate" min="0" step="0.01" value="0"></label><label>Notes<input name="notes" maxlength="2000"></label><div class="full"><button>Create project</button></div></form></section>
<section class="card"><h2>Projects</h2><?php foreach ($projects as $row): ?><div class="simple-row"><span><a href="/small-business/project/<?= e($row['id']) ?>"><strong><?= e($row['name']) ?></strong></a><small><?= e($row['client']) ?> · <?= e($row['status']) ?> · <?= e(number_format($row['hours'],2)) ?> hours</small></span><span>Income <?= money($row['income']) ?> · Cost <?= money($row['cost']) ?> · Profit <?= money($row['income']-$row['cost']) ?></span></div><?php endforeach; ?><?php if (!$projects): ?><p class="muted">No projects yet.</p><?php endif; ?></section>
